// Import di fogli di stile globali (es. `import "./globals.css"` in
// src/app/layout.tsx). Next.js dichiara solo i CSS Module (`*.module.css`):
// da TypeScript 6 `noUncheckedSideEffectImports` è attivo di default e senza
// questa dichiarazione l'import dà errore TS2882 nell'editor.
declare module "*.css";
